61: /**
62:  * \brief           Initialize buffer handle to default values with size and buffer data array
63:  * \param[in]       buff: Ring buffer instance
64:  * \param[in]       buffdata: Pointer to memory to use as buffer data
65:  * \param[in]       size: Size of `buffdata` in units of bytes
66:  *                      Maximum number of bytes buffer can hold is `size - 1`
67:  * \return          `1` on success, `0` otherwise
68:  */
69: uint8_t
70: lwrb_init(lwrb_t* buff, void* buffdata, lwrb_sz_t size) {
71:     if (buff == NULL || buffdata == NULL || size == 0) {
72:         return 0;
73:     }
74: 
75:     buff->evt_fn = NULL;
76:     buff->size = size;
77:     buff->buff = buffdata;
78:     LWRB_INIT(buff->w_ptr, 0);
79:     LWRB_INIT(buff->r_ptr, 0);
80:     return 1;
81: }
82: 
83: /**
84:  * \brief           Check if buff is initialized and ready to use
85:  * \param[in]       buff: Ring buffer instance
86:  * \return          `1` if ready, `0` otherwise
87:  */
88: uint8_t
89: lwrb_is_ready(lwrb_t* buff) {
90:     return BUF_IS_VALID(buff);
91: }
