106: /**
107:  * \brief           Set event function callback for different buffer operations
108:  * \param[in]       buff: Ring buffer instance
109:  * \param[in]       evt_fn: Callback function
110:  */
111: void
112: lwrb_set_evt_fn(lwrb_t* buff, lwrb_evt_fn evt_fn) {
113:     if (BUF_IS_VALID(buff)) {
114:         buff->evt_fn = evt_fn;
115:     }
116: }
