118: /**
119:  * \brief           Set custom buffer argument, that can be retrieved in the event function
120:  * \param[in]       buff: Ring buffer instance
121:  * \param[in]       arg: Custom user argument
122:  */
123: void
124: lwrb_set_arg(lwrb_t* buff, void* arg) {
125:     if (BUF_IS_VALID(buff)) {
126:         buff->arg = arg;
127:     }
128: }
