130: /**
131:  * \brief           Get custom buffer argument, previously set with \ref lwrb_set_arg
132:  * \param[in]       buff: Ring buffer instance
133:  * \return          User argument, previously set with \ref lwrb_set_arg
134:  */
135: void*
136: lwrb_get_arg(lwrb_t* buff) {
137:     return buff != NULL ? buff->arg : NULL;
138: }
