228: /**
229:  * \brief           Read data from buffer.
230:  *                  Copies data from `data` array to buffer and advances the read pointer for a maximum of `btr` number of bytes.
231:  * 
232:  *                  It copies less if there is less data available in the buffer.
233:  * 
234:  * \note            Use \ref lwrb_read_ex for more advanced usage
235:  *
236:  * \param[in]       buff: Ring buffer instance
237:  * \param[out]      data: Pointer to output memory to copy buffer data to
238:  * \param[in]       btr: Number of bytes to read
239:  * \return          Number of bytes read and copied to data array
240:  */
241: lwrb_sz_t
242: lwrb_read(lwrb_t* buff, void* data, lwrb_sz_t btr) {
243:     lwrb_sz_t read = 0;
244: 
245:     if (lwrb_read_ex(buff, data, btr, &read, 0)) {
246:         return read;
247:     }
248:     return 0;
249: }
