251: /**
252:  * \brief           Read extended functionality
253:  * 
254:  * \param           buff: Ring buffer instance
255:  * \param           data: Pointer to memory to write read data from buffer 
256:  * \param           btr: Number of bytes to read
257:  * \param           bread: Output pointer to write number of bytes read from buffer and written to the 
258:  *                      output `data` variable
259:  * \param           flags: Optional flags
260:  *                      \ref LWRB_FLAG_READ_ALL: Request to read all data (up to btr).
261:  *                          Will early return if no enough bytes in the buffer
262:  * \return          `1` if read operation OK, `0` otherwise
263:  */
264: uint8_t
265: lwrb_read_ex(lwrb_t* buff, void* data, lwrb_sz_t btr, lwrb_sz_t* bread, uint16_t flags) {
266:     lwrb_sz_t tocopy = 0, full = 0, r_ptr = 0;
267:     uint8_t* d_ptr = data;
268: 
269:     if (!BUF_IS_VALID(buff) || data == NULL || btr == 0) {
270:         return 0;
271:     }
272: 
273:     /* Calculate maximum number of bytes available to read */
274:     full = lwrb_get_full(buff);
275:     if (full == 0 || (full < btr && (flags & LWRB_FLAG_READ_ALL))) {
276:         return 0;
277:     }
278:     btr = BUF_MIN(full, btr);
279:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_acquire);
280: 
281:     /* Step 1: Read data from linear part of buffer */
282:     tocopy = BUF_MIN(buff->size - r_ptr, btr);
283:     BUF_MEMCPY(d_ptr, &buff->buff[r_ptr], tocopy);
284:     d_ptr += tocopy;
285:     r_ptr += tocopy;
286:     btr -= tocopy;
287: 
288:     /* Step 2: Read data from beginning of buffer (overflow part) */
289:     if (btr > 0) {
290:         BUF_MEMCPY(d_ptr, buff->buff, btr);
291:         r_ptr = btr;
292:     }
293: 
294:     /* Step 3: Check end of buffer */
295:     if (r_ptr >= buff->size) {
296:         r_ptr = 0;
297:     }
298: 
299:     /*
300:      * Write final value to the actual running variable.
301:      * This is to ensure no write operation can access intermediate data
302:      */
303:     LWRB_STORE(buff->r_ptr, r_ptr, memory_order_release);
304: 
305:     BUF_SEND_EVT(buff, LWRB_EVT_READ, tocopy + btr);
306:     if (bread != NULL) {
307:         *bread = tocopy + btr;
308:     }
309:     return 1;
310: }
