312: /**
313:  * \brief           Read from buffer without changing read pointer (peek only)
314:  * \param[in]       buff: Ring buffer instance
315:  * \param[in]       skip_count: Number of bytes to skip before reading data
316:  * \param[out]      data: Pointer to output memory to copy buffer data to
317:  * \param[in]       btp: Number of bytes to peek
318:  * \return          Number of bytes peeked and written to output array
319:  */
320: lwrb_sz_t
321: lwrb_peek(const lwrb_t* buff, lwrb_sz_t skip_count, void* data, lwrb_sz_t btp) {
322:     lwrb_sz_t full = 0, tocopy = 0, r_ptr = 0;
323:     uint8_t* d_ptr = data;
324: 
325:     if (!BUF_IS_VALID(buff) || data == NULL || btp == 0) {
326:         return 0;
327:     }
328: 
329:     /*
330:      * Calculate maximum number of bytes available to read
331:      * and check if we can even fit to it.
332:      * 
333:      * The skip count at size of buffer or above is invalid input,
334:      * thus we can safely exit the function call
335:      */
336:     full = lwrb_get_full(buff);
337:     if (skip_count >= full) {
338:         return 0;
339:     }
340:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
341:     r_ptr += skip_count;
342:     full -= skip_count;
343:     if (r_ptr >= buff->size) {
344:         r_ptr -= buff->size;
345:     }
346:     btp = BUF_MIN(full, btp);
347: 
348:     /* Step 1: Read data from linear part of the buffer */
349:     tocopy = BUF_MIN(buff->size - r_ptr, btp);
350:     BUF_MEMCPY(d_ptr, &buff->buff[r_ptr], tocopy);
351:     d_ptr += tocopy;
352:     btp -= tocopy;
353: 
354:     /* Step 2: Read data from the beginning of the buffer (overflow part) */
355:     if (btp > 0) {
356:         BUF_MEMCPY(d_ptr, buff->buff, btp);
357:     }
358:     return tocopy + btp;
359: }
