361: /**
362:  * \brief           Get available size in buffer for write operation
363:  * \param[in]       buff: Ring buffer instance
364:  * \return          Number of free bytes in memory
365:  */
366: lwrb_sz_t
367: lwrb_get_free(const lwrb_t* buff) {
368:     lwrb_sz_t size = 0, w_ptr = 0, r_ptr = 0;
369: 
370:     if (!BUF_IS_VALID(buff)) {
371:         return 0;
372:     }
373: 
374:     /*
375:      * Copy buffer pointers to local variables with atomic access.
376:      *
377:      * To ensure thread safety (only when in single-entry, single-exit FIFO mode use case),
378:      * it is important to write buffer r and w values to local w and r variables.
379:      *
380:      * Local variables will ensure below if statements will always use the same value,
381:      * even if buff->w or buff->r get changed during interrupt processing.
382:      *
383:      * They may change during load operation, important is that
384:      * they do not change during if-else operations following these assignments.
385:      *
386:      * lwrb_get_free is only called for write purpose, and when in FIFO mode, then:
387:      * - buff->w pointer will not change by another process/interrupt because we are in write mode just now
388:      * - buff->r pointer may change by another process. If it gets changed after buff->r has been loaded to local variable,
389:      *    buffer will see "free size" less than it actually is. This is not a problem, application can
390:      *    always try again to write more data to remaining free memory that was read just during copy operation
391:      */
392:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
393:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
394: 
395:     if (w_ptr >= r_ptr) {
396:         size = buff->size - (w_ptr - r_ptr);
397:     } else {
398:         size = r_ptr - w_ptr;
399:     }
400: 
401:     /* Buffer free size is always 1 less than actual size */
402:     return size - 1;
403: }
404: 
405: /**
406:  * \brief           Get number of bytes currently available in buffer
407:  * \param[in]       buff: Ring buffer instance
408:  * \return          Number of bytes ready to be read
409:  */
410: lwrb_sz_t
411: lwrb_get_full(const lwrb_t* buff) {
412:     lwrb_sz_t size = 0, w_ptr = 0, r_ptr = 0;
413: 
414:     if (!BUF_IS_VALID(buff)) {
415:         return 0;
416:     }
417: 
418:     /*
419:      * Copy buffer pointers to local variables.
420:      *
421:      * To ensure thread safety (only when in single-entry, single-exit FIFO mode use case),
422:      * it is important to write buffer r and w values to local w and r variables.
423:      *
424:      * Local variables will ensure below if statements will always use the same value,
425:      * even if buff->w or buff->r get changed during interrupt processing.
426:      *
427:      * They may change during load operation, important is that
428:      * they do not change during if-else operations following these assignments.
429:      *
430:      * lwrb_get_full is only called for read purpose, and when in FIFO mode, then:
431:      * - buff->r pointer will not change by another process/interrupt because we are in read mode just now
432:      * - buff->w pointer may change by another process. If it gets changed after buff->w has been loaded to local variable,
433:      *    buffer will see "full size" less than it really is. This is not a problem, application can
434:      *    always try again to read more data from remaining full memory that was written just during copy operation
435:      */
436:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
437:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
438: 
439:     if (w_ptr >= r_ptr) {
440:         size = w_ptr - r_ptr;
441:     } else {
442:         size = buff->size - (r_ptr - w_ptr);
443:     }
444:     return size;
445: }
