447: /**
448:  * \brief           Resets buffer to default values. Buffer size is not modified
449:  * \note            This function is not thread safe.
450:  *                      When used, application must ensure there is no active read/write operation
451:  * \param[in]       buff: Ring buffer instance
452:  */
453: void
454: lwrb_reset(lwrb_t* buff) {
455:     if (BUF_IS_VALID(buff)) {
456:         LWRB_STORE(buff->w_ptr, 0, memory_order_release);
457:         LWRB_STORE(buff->r_ptr, 0, memory_order_release);
458:         BUF_SEND_EVT(buff, LWRB_EVT_RESET, 0);
459:     }
460: }
