462: /**
463:  * \brief           Get linear address for buffer for fast read
464:  * \param[in]       buff: Ring buffer instance
465:  * \return          Linear buffer start address
466:  */
467: void*
468: lwrb_get_linear_block_read_address(const lwrb_t* buff) {
469:     lwrb_sz_t ptr = 0;
470: 
471:     if (!BUF_IS_VALID(buff)) {
472:         return NULL;
473:     }
474:     ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
475:     return &buff->buff[ptr];
476: }
