508: /**
509:  * \brief           Skip (ignore; advance read pointer) buffer data
510:  * Marks data as read in the buffer and increases free memory for up to `len` bytes
511:  *
512:  * \note            Useful at the end of streaming transfer such as DMA
513:  * \param[in]       buff: Ring buffer instance
514:  * \param[in]       len: Number of bytes to skip and mark as read
515:  * \return          Number of bytes skipped
516:  */
517: lwrb_sz_t
518: lwrb_skip(lwrb_t* buff, lwrb_sz_t len) {
519:     lwrb_sz_t full = 0, r_ptr = 0;
520: 
521:     if (!BUF_IS_VALID(buff) || len == 0) {
522:         return 0;
523:     }
524: 
525:     full = lwrb_get_full(buff);
526:     len = BUF_MIN(len, full);
527:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_acquire);
528:     r_ptr += len;
529:     if (r_ptr >= buff->size) {
530:         r_ptr -= buff->size;
531:     }
532:     LWRB_STORE(buff->r_ptr, r_ptr, memory_order_release);
533:     BUF_SEND_EVT(buff, LWRB_EVT_READ, len);
534:     return len;
535: }
536: 
537: /**
538:  * \brief           Get linear address for buffer for fast write
539:  * \param[in]       buff: Ring buffer instance
540:  * \return          Linear buffer start address
541:  */
542: void*
543: lwrb_get_linear_block_write_address(const lwrb_t* buff) {
544:     lwrb_sz_t ptr = 0;
545: 
546:     if (!BUF_IS_VALID(buff)) {
547:         return NULL;
548:     }
549:     ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
550:     return &buff->buff[ptr];
551: }
