553: /**
554:  * \brief           Get length of linear block address before it overflows for write operation
555:  * \param[in]       buff: Ring buffer instance
556:  * \return          Linear buffer size in units of bytes for write operation
557:  */
558: lwrb_sz_t
559: lwrb_get_linear_block_write_length(const lwrb_t* buff) {
560:     lwrb_sz_t len = 0, w_ptr = 0, r_ptr = 0;
561: 
562:     if (!BUF_IS_VALID(buff)) {
563:         return 0;
564:     }
565: 
566:     /*
567:      * Use temporary values in case they are changed during operations.
568:      * See lwrb_buff_free or lwrb_buff_full functions for more information why this is OK.
569:      */
570:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_relaxed);
571:     r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
572: 
573:     if (w_ptr >= r_ptr) {
574:         len = buff->size - w_ptr;
575:         /*
576:          * When read pointer is 0,
577:          * maximal length is one less as if too many bytes
578:          * are written, buffer would be considered empty again (r == w)
579:          */
580:         if (r_ptr == 0) {
581:             /*
582:              * Cannot overflow:
583:              * - If r is not 0, statement does not get called
584:              * - buff->size cannot be 0 and if r is 0, len is greater 0
585:              */
586:             --len;
587:         }
588:     } else {
589:         len = r_ptr - w_ptr - 1;
590:     }
591:     return len;
592: }
