594: /**
595:  * \brief           Advance write pointer in the buffer.
596:  * Similar to skip function but modifies write pointer instead of read
597:  *
598:  * \note            Useful when hardware is writing to buffer and application needs to increase number
599:  *                      of bytes written to buffer by hardware
600:  * \param[in]       buff: Ring buffer instance
601:  * \param[in]       len: Number of bytes to advance
602:  * \return          Number of bytes advanced for write operation
603:  */
604: lwrb_sz_t
605: lwrb_advance(lwrb_t* buff, lwrb_sz_t len) {
606:     lwrb_sz_t free = 0, w_ptr = 0;
607: 
608:     if (!BUF_IS_VALID(buff) || len == 0) {
609:         return 0;
610:     }
611: 
612:     /* Use local variables before writing back to main structure */
613:     free = lwrb_get_free(buff);
614:     len = BUF_MIN(len, free);
615:     w_ptr = LWRB_LOAD(buff->w_ptr, memory_order_acquire);
616:     w_ptr += len;
617:     if (w_ptr >= buff->size) {
618:         w_ptr -= buff->size;
619:     }
620:     LWRB_STORE(buff->w_ptr, w_ptr, memory_order_release);
621:     BUF_SEND_EVT(buff, LWRB_EVT_WRITE, len);
622:     return len;
623: }
