625: /**
626:  * \brief           Searches for a *needle* in an array, starting from given offset.
627:  * 
628:  * \note            This function is not thread-safe. 
629:  * 
630:  * \param           buff: Ring buffer to search for needle in
631:  * \param           bts: Constant byte array sequence to search for in a buffer
632:  * \param           len: Length of the \arg bts array 
633:  * \param           start_offset: Start offset in the buffer
634:  * \param           found_idx: Pointer to variable to write index in array where bts has been found
635:  *                      Must not be set to `NULL`
636:  * \return          `1` if \arg bts found, `0` otherwise
637:  */
638: uint8_t
639: lwrb_find(const lwrb_t* buff, const void* bts, lwrb_sz_t len, lwrb_sz_t start_offset, lwrb_sz_t* found_idx) {
640:     lwrb_sz_t full = 0, r_ptr = 0, buff_r_ptr = 0, max_x = 0;
641:     uint8_t found = 0;
642:     const uint8_t* needle = bts;
643: 
644:     if (!BUF_IS_VALID(buff) || needle == NULL || len == 0 || found_idx == NULL) {
645:         return 0;
646:     }
647:     *found_idx = 0;
648: 
649:     full = lwrb_get_full(buff);
650:     /* Verify initial conditions */
651:     if (full < (len + start_offset)) {
652:         return 0;
653:     }
654: 
655:     /* Get actual buffer read pointer for this search */
656:     buff_r_ptr = LWRB_LOAD(buff->r_ptr, memory_order_relaxed);
657: 
658:     /* Max number of for loops is buff_full - input_len - start_offset of buffer length */
659:     max_x = full - len;
660:     for (lwrb_sz_t skip_x = start_offset; !found && skip_x <= max_x; ++skip_x) {
661:         found = 1; /* Found by default */
662: 
663:         /* Prepare the starting point for reading */
664:         r_ptr = buff_r_ptr + skip_x;
665:         if (r_ptr >= buff->size) {
666:             r_ptr -= buff->size;
667:         }
668: 
669:         /* Search in the buffer */
670:         for (lwrb_sz_t idx = 0; idx < len; ++idx) {
671:             if (buff->buff[r_ptr] != needle[idx]) {
672:                 found = 0;
673:                 break;
674:             }
675:             if (++r_ptr >= buff->size) {
676:                 r_ptr = 0;
677:             }
678:         }
679:         if (found) {
680:             *found_idx = skip_x;
681:         }
682:     }
683:     return found;
684: }

